// Pure: the slash-command table (one name per resource), scope shape and edits,
// resource rows, the prompt block and the /foundry context tree.
// Everything that runs orthanc stays in register.tsx, where `$` lives.

import type {
  FoundryNamed,
  FoundryObjectType,
  FoundryPickerKind,
  FoundryResource,
  FoundryResourceKind,
  FoundryScope,
} from '../types'
import { isRecord } from './orthanc'

/** Compass resource kinds orthanc lists with `resource list|search --type`. */
export const COMPASS_KINDS = {
  folders: { label: 'Folders', typeId: 'COMPASS_FOLDER' },
  datasets: { label: 'Datasets', typeId: 'FOUNDRY_DATASET' },
  mediaSets: { label: 'Media sets', typeId: 'MIO_MEDIA_SET' },
  repositories: { label: 'Repositories', typeId: 'STEMMA_REPOSITORY' },
  contourAnalyses: { label: 'Contour analyses', typeId: 'CONTOUR_ANALYSIS' },
  sources: { label: 'Sources', typeId: 'MAGRITTE_SOURCE' },
  developerConsoles: { label: 'Developer Console', typeId: 'THIRD_PARTY_APPLICATIONS_APPLICATION' },
  aipChatbots: { label: 'AIP chatbots', typeId: 'AIP_AGENTS_AGENT' },
} as const
export type CompassKind = keyof typeof COMPASS_KINDS

export const RESOURCE_LABELS: Record<FoundryResourceKind, string> = {
  ...Object.fromEntries(Object.entries(COMPASS_KINDS).map(([kind, def]) => [kind, def.label])),
  mediaItems: 'Media items',
  objectInstances: 'Object instances',
  functions: 'Functions',
  languageModels: 'Language models',
  permissions: 'Permissions',
  searchResults: 'Search results',
} as Record<FoundryResourceKind, string>

/** Resource kinds that belong to the ontology and go when it changes. */
const ONTOLOGY_KINDS: readonly FoundryResourceKind[] = ['objectInstances', 'functions']

export type Lookup = 'media-item' | 'objects' | 'function' | 'language-model' | 'permission' | 'search'

export type CommandAction =
  | { type: 'picker'; kind: Exclude<FoundryPickerKind, 'resource'> }
  | { type: 'resource'; kind: CompassKind }
  | { type: 'lookup'; lookup: Lookup; kind: FoundryResourceKind }
  | { type: 'blocked'; bead: string; what: string }
  | { type: 'open' | 'onboard' | 'auth' | 'scope' | 'approval' | 'mcp-status' | 'foundry' | 'trace' | 'fde' }

export type CommandEntry = { name: string; description: string; argumentHint?: string; action: CommandAction }

const CLEARABLE = '[filter | clear]'
const LINK_BEAD = 'orthanc-ra6'
const LISTING_BEAD = 'orthanc-qm5'
export const OBJECT_QUERY_BEAD = 'orthanc-4f7'

const picker = (name: string, kind: Exclude<FoundryPickerKind, 'resource'>, description: string): CommandEntry => ({
  name,
  description,
  argumentHint: kind === 'profile' ? '[name]' : CLEARABLE,
  action: { type: 'picker', kind },
})
const resource = (name: string, kind: CompassKind): CommandEntry => ({
  name,
  description: `Choose ${COMPASS_KINDS[kind].label.toLowerCase()} in scope`,
  argumentHint: CLEARABLE,
  action: { type: 'resource', kind },
})
const blocked = (name: string, what: string, bead: string): CommandEntry =>
  ({ name, description: `Choose ${what} (waits on orthanc ${bead})`, action: { type: 'blocked', bead, what } })

export const COMMAND_TABLE: readonly CommandEntry[] = [
  { name: 'foundry', description: 'Show the Foundry resources in context (like /context, for Palantir)', action: { type: 'foundry' } },
  { name: 'open', description: 'Set working context: stack, then ontology and projects', action: { type: 'open' } },
  { name: 'onboard', description: 'Check Foundry setup: orthanc, stack, credentials, context', action: { type: 'onboard' } },
  { name: 'auth', description: 'Show how to authenticate a Foundry stack', argumentHint: '[profile]', action: { type: 'auth' } },
  picker('profile', 'profile', 'Choose the Foundry stack (orthanc profile)'),
  picker('ontology', 'ontology', 'Choose the active Foundry ontology'),
  picker('project', 'project', 'Choose the Foundry projects in scope'),
  picker('object-type', 'object-type', 'Choose the ontology object types in scope'),
  picker('action-type', 'action-type', 'Choose the ontology action types in scope'),
  blocked('link-type', 'ontology link types', LINK_BEAD),
  blocked('interface', 'ontology interfaces', LINK_BEAD),
  resource('folder', 'folders'),
  resource('dataset', 'datasets'),
  resource('media-set', 'mediaSets'),
  resource('repository', 'repositories'),
  resource('contour', 'contourAnalyses'),
  resource('source', 'sources'),
  resource('developer-console', 'developerConsoles'),
  resource('aip-chatbot', 'aipChatbots'),
  blocked('egress-policy', 'egress policies', LISTING_BEAD),
  blocked('certificate', 'certificates', LISTING_BEAD),
  blocked('automation', 'automations', LISTING_BEAD),
  {
    name: 'media-item',
    description: 'Add a media item by media-set RID and item path or RID',
    argumentHint: '<media-set-rid> <path|rid> | clear',
    action: { type: 'lookup', lookup: 'media-item', kind: 'mediaItems' },
  },
  {
    name: 'objects',
    description: 'Search object instances of the selected object types',
    argumentHint: '<property>=<text> | clear',
    action: { type: 'lookup', lookup: 'objects', kind: 'objectInstances' },
  },
  {
    name: 'function',
    description: 'Search Foundry functions and add them to context',
    argumentHint: '<query> | clear',
    action: { type: 'lookup', lookup: 'function', kind: 'functions' },
  },
  {
    name: 'language-model',
    description: 'Choose the stack language models in context',
    argumentHint: CLEARABLE,
    action: { type: 'lookup', lookup: 'language-model', kind: 'languageModels' },
  },
  {
    name: 'permission',
    description: 'Inspect role grants on a resource and add them to context',
    argumentHint: '<resource-rid> | clear',
    action: { type: 'lookup', lookup: 'permission', kind: 'permissions' },
  },
  {
    name: 'search',
    description: 'Search Foundry resource titles across the stack',
    argumentHint: '<text> | clear',
    action: { type: 'lookup', lookup: 'search', kind: 'searchResults' },
  },
  { name: 'scope', description: 'Show the Foundry context; `clear` resets it, `ontology` re-picks it', argumentHint: '[show | clear | ontology]', action: { type: 'scope' } },
  { name: 'approval', description: 'Show or set the Foundry approval mode, or show the guard rules', argumentHint: '[mode|rules]', action: { type: 'approval' } },
  {
    name: 'fde',
    description: 'FDE mode: bind this session to one agent branch; writes plan before they apply',
    argumentHint: 'on | <goal> | goal <text> | --branch <rid> [goal] | resume | end',
    action: { type: 'fde' },
  },
  { name: 'trace', description: 'Show trace export status (Langfuse/OTLP) and check the last Foundry trace landed', action: { type: 'trace' } },
  { name: 'mcp-status', description: 'Show Orthanc and Foundry stack status', action: { type: 'mcp-status' } },
]

export const blockedText = (what: string, bead: string) =>
  `Orthanc cannot list ${what} yet, so this command is waiting on bead ${bead} ` +
  `in the orthanc tracker. It does not fall back to Foundry REST.`

// ---------- scope ----------

const asString = (value: unknown) => (typeof value === 'string' ? value : '')

const named = (value: unknown): FoundryNamed | null =>
  isRecord(value) && typeof value.rid === 'string' ? { rid: value.rid, name: asString(value.name) || value.rid } : null

const types = (value: unknown): FoundryObjectType[] =>
  Array.isArray(value)
    ? value.filter(isRecord).flatMap(entry =>
        typeof entry.apiName === 'string'
          ? [{ apiName: entry.apiName, displayName: asString(entry.displayName) || entry.apiName, ...(typeof entry.rid === 'string' ? { rid: entry.rid } : {}) }]
          : [],
      )
    : []

const resourcesOf = (value: unknown): FoundryResource[] =>
  Array.isArray(value)
    ? value.filter(isRecord).flatMap(entry =>
        typeof entry.rid === 'string' ? [{ rid: entry.rid, name: asString(entry.name) || entry.rid, hint: asString(entry.hint) }] : [],
      )
    : []

export const emptyScope = (profile: string, host: string): FoundryScope => ({
  profile,
  host,
  ontology: null,
  projects: [],
  objectTypes: [],
  actionTypes: [],
  resources: {},
  updatedAt: new Date().toISOString(),
})

/** Any stored value (v0.1 scopes included) as a whole FoundryScope. */
export function normalizeScope(value: unknown, profile: string, host: string): FoundryScope {
  if (!isRecord(value)) return emptyScope(profile, host)
  const resources: FoundryScope['resources'] = {}
  if (isRecord(value.resources)) {
    for (const kind of Object.keys(RESOURCE_LABELS) as FoundryResourceKind[]) {
      const list = resourcesOf(value.resources[kind])
      if (list.length > 0) resources[kind] = list
    }
  }
  return {
    profile: asString(value.profile) || profile,
    host: asString(value.host) || host,
    ontology: named(value.ontology),
    projects: Array.isArray(value.projects) ? value.projects.map(named).filter((entry): entry is FoundryNamed => entry !== null) : [],
    objectTypes: types(value.objectTypes),
    actionTypes: types(value.actionTypes),
    resources,
    updatedAt: asString(value.updatedAt) || new Date().toISOString(),
  }
}

export function ontologyChanged(scope: FoundryScope, ontology: FoundryNamed | null): FoundryScope {
  const resources = { ...scope.resources }
  for (const kind of ONTOLOGY_KINDS) resources[kind] = []
  return { ...scope, ontology, projects: [], objectTypes: [], actionTypes: [], resources }
}

// ---------- orthanc rows ----------

export function resourceArgs(query: string, typeId: string, root: string): string[] {
  const trimmed = query.trim()
  return [...(trimmed ? ['resource', 'search', trimmed] : ['resource', 'list']), '--type', typeId, '--folder-rid', root]
}

/** orthanc rows as resources: RID required, first RID wins. */
export function resourceRows(rows: readonly Record<string, unknown>[], hintKeys: readonly string[] = ['path', 'type']): FoundryResource[] {
  const seen = new Set<string>()
  return rows.flatMap(row => {
    const rid = asString(row.rid) || asString(row.__rid) || asString(row.api_name) || asString(row.apiName)
    if (!rid || seen.has(rid)) return []
    seen.add(rid)
    const name =
      asString(row.display_name) || asString(row.displayName) || asString(row.name) || asString(row.__title) || asString(row.api_name) || rid
    const hint = hintKeys.map(key => row[key]).map(value => (isRecord(value) ? asString(value.name) : asString(value))).find(Boolean) ?? ''
    return [{ rid, name, hint }]
  })
}

/** The new selection, plus earlier selections the listing did not show. */
export function mergeSelections(
  existing: readonly FoundryResource[],
  selected: readonly FoundryResource[],
  visible: readonly FoundryResource[],
): FoundryResource[] {
  const shown = new Set(visible.map(entry => entry.rid))
  return [...existing.filter(entry => !shown.has(entry.rid)), ...selected]
}

export function objectsQuery(args: string): { property: string; text: string } | null {
  const match = /^\s*([A-Za-z_][\w.]*)\s*=\s*(.+?)\s*$/.exec(args)
  return match?.[1] && match[2] ? { property: match[1], text: match[2] } : null
}

// ---------- prompt block ----------

const list = (entries: readonly FoundryResource[]) => entries.map(entry => `${entry.name} (${entry.rid})`).join(', ')

export function contextLines(scope: FoundryScope): string[] {
  const lines: string[] = []
  if (scope.ontology) lines.push(`Ontology: ${scope.ontology.name} (${scope.ontology.rid}).`)
  if (scope.projects.length > 0) {
    lines.push(`Projects: ${scope.projects.map(project => `${project.name} (${project.rid})`).join(', ')}.`)
    lines.push('Keep project discovery within the selected project subtrees.')
  }
  if (scope.objectTypes.length > 0) {
    lines.push(`Object types: ${scope.objectTypes.map(type => `${type.displayName} (${type.apiName})`).join(', ')}.`)
  }
  if (scope.actionTypes.length > 0) {
    lines.push(`Action types: ${scope.actionTypes.map(type => `${type.displayName} (${type.apiName})`).join(', ')}.`)
  }
  for (const [kind, label] of Object.entries(RESOURCE_LABELS) as [FoundryResourceKind, string][]) {
    const entries = scope.resources[kind] ?? []
    if (entries.length > 0) lines.push(`${label}: ${list(entries)}.`)
  }
  return lines
}

export const hasFocus = (scope: FoundryScope) =>
  scope.ontology !== null || scope.projects.length > 0 || Object.values(scope.resources).some(entries => (entries?.length ?? 0) > 0)

// ---------- /foundry tree ----------

export type ClearTarget =
  | { type: 'ontology' }
  | { type: 'projects' | 'objectTypes' | 'actionTypes' }
  | { type: 'resource'; kind: FoundryResourceKind }
  | { type: 'item'; section: 'projects' | 'objectTypes' | 'actionTypes'; key: string }
  | { type: 'resource-item'; kind: FoundryResourceKind; rid: string }

export type TreeNode = { id: string; label: string; detail: string; count: number; command: string; clear?: ClearTarget; children: TreeNode[] }

const leaf = (id: string, label: string, detail: string, clear: ClearTarget): TreeNode => ({ id, label, detail, count: 0, command: '', clear, children: [] })

const COMMAND_FOR: Record<FoundryResourceKind, string> = {
  folders: '/folder',
  datasets: '/dataset',
  mediaSets: '/media-set',
  mediaItems: '/media-item',
  repositories: '/repository',
  contourAnalyses: '/contour',
  sources: '/source',
  developerConsoles: '/developer-console',
  aipChatbots: '/aip-chatbot',
  objectInstances: '/objects',
  functions: '/function',
  languageModels: '/language-model',
  permissions: '/permission',
  searchResults: '/search',
}

/** The sections that hold something, top-level, in reading order. */
export function foundryTree(scope: FoundryScope): TreeNode[] {
  const nodes: TreeNode[] = []
  if (scope.ontology) {
    nodes.push({ id: 'ontology', label: 'Ontology', detail: scope.ontology.name, count: 1, command: '/ontology', clear: { type: 'ontology' }, children: [] })
  }
  const typed = (id: 'projects' | 'objectTypes' | 'actionTypes', label: string, command: string, entries: { key: string; label: string; detail: string }[]) => {
    if (entries.length === 0) return
    nodes.push({
      id,
      label,
      detail: '',
      count: entries.length,
      command,
      clear: { type: id },
      children: entries.map(entry => leaf(`${id}:${entry.key}`, entry.label, entry.detail, { type: 'item', section: id, key: entry.key })),
    })
  }
  typed('projects', 'Projects', '/project', scope.projects.map(project => ({ key: project.rid, label: project.name, detail: project.rid })))
  typed('objectTypes', 'Object types', '/object-type', scope.objectTypes.map(type => ({ key: type.apiName, label: type.displayName, detail: type.apiName })))
  typed('actionTypes', 'Action types', '/action-type', scope.actionTypes.map(type => ({ key: type.apiName, label: type.displayName, detail: type.apiName })))
  for (const [kind, label] of Object.entries(RESOURCE_LABELS) as [FoundryResourceKind, string][]) {
    const entries = scope.resources[kind] ?? []
    if (entries.length === 0) continue
    nodes.push({
      id: `resource:${kind}`,
      label,
      detail: '',
      count: entries.length,
      command: COMMAND_FOR[kind],
      clear: { type: 'resource', kind },
      children: entries.map(entry => leaf(`${kind}:${entry.rid}`, entry.name, entry.hint || entry.rid, { type: 'resource-item', kind, rid: entry.rid })),
    })
  }
  return nodes
}

export function applyClear(scope: FoundryScope, target: ClearTarget): FoundryScope {
  switch (target.type) {
    case 'ontology':
      return ontologyChanged(scope, null)
    case 'projects':
    case 'objectTypes':
    case 'actionTypes':
      return { ...scope, [target.type]: [] }
    case 'resource':
      return { ...scope, resources: { ...scope.resources, [target.kind]: [] } }
    case 'resource-item':
      return {
        ...scope,
        resources: { ...scope.resources, [target.kind]: (scope.resources[target.kind] ?? []).filter(entry => entry.rid !== target.rid) },
      }
    case 'item':
      if (target.section === 'projects') return { ...scope, projects: scope.projects.filter(entry => entry.rid !== target.key) }
      return { ...scope, [target.section]: scope[target.section].filter(entry => entry.apiName !== target.key) }
  }
}

files.hooks/fde.ts:
// FDE mode (/fde): one session, one goal, one agent global branch. Pure
// functions, shared by the hooks and the tests. The mode only adds checks: the
// branch rule, the ladder and the destructive rule run as they do without it.
//
// While bound:
//  - every ontology write is pinned to the session's global branch (injected
//    when the call names none, refused when it names another);
//  - no global-branch or proposal changes (but add-repo on the bound branch):
//    closing or merging is the operator's;
//  - --apply runs only after a clean dry run of the same call, with every file
//    it reads pinned by SHA-256; each dry run licenses one apply.

import type { FdeSession } from '../types'
import { BRANCH_FLAGS, flagValues, requiresBranch, unquote, validateBranchName } from './policy'

const PREFIX = 'agent/fde-'
const NAME_MAX = 64
const GOAL_MAX = 200
const RECORD_MAX = 50
const GLOBAL_BRANCH = /^ri\.branch\.\.branch\.[A-Za-z0-9-]+$/
const GLOBAL_BRANCH_ANY = /ri\.branch\.\.branch\.[A-Za-z0-9-]+/g
const ONTOLOGY_RID = /ri\.ontology\.main\.ontology\.[A-Za-z0-9-]+/g
// Flags that could be read as a branch flag by a lenient parser: a --br… prefix, or -b inside a bundle.
const AMBIGUOUS_BRANCH_FLAG = /^(--br(?!anch(=|$))[a-z-]*(=.*)?|-[a-z]*b[a-z]+|-[a-z]+b)$/i
const PROFILE_FLAG = /^--profile(=|$)/
// While bound, only this branch command runs, and only on the bound branch.
const GLOBAL_BRANCH_ALLOWED = new Set(['global-branch add-repo'])

/** One line, no control characters, at most 200 characters. */
const cleanGoal = (text: string) =>
  text
    .replace(/[\u0000-\u001f\u007f]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, GOAL_MAX)

export type FdeArgs =
  | { kind: 'status' }
  | { kind: 'end' }
  | { kind: 'resume' }
  | { kind: 'start'; goal: string }
  | { kind: 'adopt'; rid: string; goal: string }
  | { kind: 'goal'; goal: string }
  | { kind: 'error'; reason: string }

/** The goal as shown; a session started with /fde on has none until /fde goal sets one. */
export const goalLabel = (goal: string) => (goal === '' ? 'no goal set' : goal)

export function parseFdeArgs(text: string): FdeArgs {
  const trimmed = text.trim()
  if (trimmed === '' || trimmed === 'status') return { kind: 'status' }
  if (trimmed === 'end') return { kind: 'end' }
  if (trimmed === 'resume') return { kind: 'resume' }
  if (trimmed.toLowerCase() === 'on') return { kind: 'start', goal: '' }
  const setGoal = /^goal(?:\s+([\s\S]*))?$/.exec(trimmed)
  if (setGoal) {
    const goal = cleanGoal(setGoal[1] ?? '')
    return goal === '' ? { kind: 'error', reason: 'Name the goal: /fde goal <text>.' } : { kind: 'goal', goal }
  }
  const adopt = /^--branch(?:=|\s+)(\S+)\s*([\s\S]*)$/.exec(trimmed)
  if (adopt) {
    const rid = adopt[1]!
    const goal = cleanGoal(adopt[2] ?? '')
    if (!GLOBAL_BRANCH.test(rid)) return { kind: 'error', reason: `'${rid}' is not a global branch RID (ri.branch..branch.…).` }
    return { kind: 'adopt', rid, goal }
  }
  return { kind: 'start', goal: cleanGoal(trimmed) }
}

const stamp = (now: Date) => now.toISOString().replace(/\D/g, '').slice(0, 12)

/** agent/fde-<goal slug>-<yyyymmddhhmm>, at most 64 characters, valid for global-branch create. */
export function fdeBranchName(goal: string, now: Date): string {
  const suffix = `-${stamp(now)}`
  const room = NAME_MAX - PREFIX.length - suffix.length
  let slug = goal
    .normalize('NFKD')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
  if (slug.length > room) slug = slug.slice(0, room).replace(/-[^-]*$/, '') || slug.slice(0, room)
  slug = slug.replace(/-+$/, '')
  const name = slug === '' ? `${PREFIX}${stamp(now)}` : `${PREFIX}${slug}${suffix}`
  return validateBranchName('global-branch create', name).ok ? name : `${PREFIX}work${suffix}`
}

export function branchCreateArgs(name: string, ontologyRid: string, goal: string): string[] {
  return ['global-branch', 'create', name, '--ontology-rid', ontologyRid, '--description', (goal === '' ? 'claude-foundry FDE session' : `claude-foundry FDE: ${goal}`).slice(0, GOAL_MAX), '--apply']
}

/** The global branch RID in a clean orthanc envelope; null on errors or none. */
export function branchRidFrom(envelope: { data?: unknown; errors?: unknown }): string | null {
  if (Array.isArray(envelope.errors) && envelope.errors.length > 0) return null
  const found = /ri\.branch\.\.branch\.[A-Za-z0-9-]+/.exec(JSON.stringify(envelope.data ?? null))
  return found ? found[0] : null
}

export const hasApply = (args: readonly string[]) => args.some(arg => /^--apply(=.*)?$/.test(unquote(arg)))

const FILE_FLAG = /^--(?:[a-z0-9-]+-)?file$/
const absolute = (path: string, cwd: string, home: string) => {
  const expanded = home !== '' ? path.replace(/^~(?=\/|$)/, home) : path
  return expanded.startsWith('/') ? expanded : `${cwd.replace(/\/$/, '')}/${expanded}`
}
// Any word that could name a file: not a flag, RID, URL or number. A word that
// is not a file simply does not read, and is left out of the plan.
const looksLikePath = (value: string) =>
  value !== '' && !value.startsWith('-') && !/^ri\./.test(value) && !/^[a-z]+:\/\//i.test(value) && !/^[0-9.:]+$/.test(value) && !/[\n{}]/.test(value)

/** Files a call may read, absolute against `cwd`: `required` (values of --file
 * and --*-file flags, and @name references) must be readable; `optional`
 * (every other word that could be a path) is hashed when it reads. Directories
 * do not read, so their contents are not pinned. */
export function fileCandidates(args: readonly string[], cwd: string, home = ''): { required: string[]; optional: string[] } {
  const required: string[] = []
  const optional: string[] = []
  for (let index = 0; index < args.length; index += 1) {
    const arg = unquote(args[index] ?? '')
    if (FILE_FLAG.test(arg) && args[index + 1] !== undefined) {
      required.push(absolute(unquote(args[index + 1]!).replace(/^@/, ''), cwd, home))
      index += 1
      continue
    }
    const joined = /^(--[a-z0-9-]+)=(.+)$/i.exec(arg)
    const raw = joined ? unquote(joined[2]!) : arg
    const value = raw.replace(/^@/, '')
    if ((joined && FILE_FLAG.test(joined[1]!)) || (raw.startsWith('@') && value !== '')) required.push(absolute(value, cwd, home))
    else if (looksLikePath(value)) optional.push(absolute(value, cwd, home))
  }
  return { required, optional }
}

/** SHA-256 of the text, with its length: what a plan pins a file to. */
export async function contentHash(text: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text))
  return `${text.length}:${Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('')}`
}

/** One call, --apply removed, with the hash of every file it reads. */
export function planSignature(path: string, args: readonly string[], fileHashes: Record<string, string>): string {
  const kept = args.filter(arg => !/^--apply(=.*)?$/.test(unquote(arg))).map(unquote)
  const files = Object.keys(fileHashes)
    .sort()
    .map(file => [file, fileHashes[file]])
  return JSON.stringify([path, kept, files])
}

export function planGate(fde: FdeSession, signature: string, isApply: boolean): string | null {
  if (!isApply || fde.plans.includes(signature)) return null
  return (
    'FDE mode: --apply runs only after a clean dry run of the same call. Run it without --apply first, ' +
    'read the plan, then apply with identical arguments. Each dry run licenses one apply, and editing a file the call reads voids it.'
  )
}

export const recordPlan = (fde: FdeSession, signature: string): FdeSession =>
  fde.plans.includes(signature) ? fde : { ...fde, plans: [...fde.plans, signature].slice(-RECORD_MAX) }

/** Takes the plan for one apply, so a second identical apply (even in parallel) finds it gone. */
export function takePlan(fde: FdeSession, signature: string): { fde: FdeSession; taken: boolean } {
  if (!fde.plans.includes(signature)) return { fde, taken: false }
  return { fde: { ...fde, plans: fde.plans.filter(plan => plan !== signature) }, taken: true }
}

/** Why a file the call reads is refused: it names another global branch or ontology. */
export function foreignRids(fde: FdeSession, text: string): string | null {
  const branches = new Set(text.match(GLOBAL_BRANCH_ANY) ?? [])
  branches.delete(fde.branchRid)
  const ontologies = new Set(text.match(ONTOLOGY_RID) ?? [])
  ontologies.delete(fde.ontologyRid)
  const found = [...branches, ...ontologies]
  return found.length === 0 ? null : `a file this call reads names ${found.join(', ')}; the session works on ${fde.branchRid} in ${fde.ontologyRid} only.`
}

/** An apply consumes its dry run: the next apply needs a new one. */
export const recordApply = (fde: FdeSession, command: string, signature: string, now: Date): FdeSession => ({
  ...fde,
  plans: fde.plans.filter(plan => plan !== signature),
  applied: [...fde.applied, { command, at: now.toISOString() }].slice(-RECORD_MAX),
})

/** Binds one orthanc_cli call to the session: the (possibly rewritten) args, or why it is refused. */
export function fdeBind(
  fde: FdeSession,
  path: string,
  args: readonly string[],
  profile: string,
  isMutation: boolean,
): { args: string[] } | { deny: string } {
  const tag = `FDE mode (${fde.branchName})`
  const words = args.map(unquote)
  // The stack is the session's: no call may switch it, read or write.
  if (words.some(word => PROFILE_FLAG.test(word))) return { deny: `${tag}: --profile is not allowed while bound; the session runs on stack '${fde.profile}'.` }
  if (!isMutation) return { args: [...args] }
  if (profile !== fde.profile) {
    return { deny: `${tag}: the session's branch is on stack '${fde.profile}', but the active stack is '${profile}'. Switch back with /profile ${fde.profile}, or /fde end.` }
  }
  if (path === 'global-branch create') {
    return { deny: `${tag}: this session works on ${fde.branchRid} only. Do not create another global branch; the operator ends the mode with /fde end.` }
  }
  if ((path.startsWith('global-branch ') && !GLOBAL_BRANCH_ALLOWED.has(path)) || path.startsWith('proposal ')) {
    return { deny: `${tag}: '${path}' changes branches or proposals, which is the operator's decision at handoff. Report that the work is ready instead.` }
  }
  const foreign = new Set(words.flatMap(word => word.match(GLOBAL_BRANCH_ANY) ?? []))
  foreign.delete(fde.branchRid)
  if (foreign.size > 0) return { deny: `${tag}: this call names ${[...foreign].join(', ')}; the session works on ${fde.branchRid} only.` }
  if (path.startsWith('global-branch ') && !words.includes(fde.branchRid)) {
    return { deny: `${tag}: '${path}' must name the session's branch ${fde.branchRid}.` }
  }
  const ontologies = new Set(words.flatMap(word => word.match(ONTOLOGY_RID) ?? []))
  ontologies.delete(fde.ontologyRid)
  if (ontologies.size > 0) {
    return { deny: `${tag}: the branch belongs to ontology ${fde.ontologyRid}; this call names ${[...ontologies].join(', ')}.` }
  }
  if (!path.startsWith('ontology ')) return { args: [...args] }
  if (words.some(word => AMBIGUOUS_BRANCH_FLAG.test(word))) {
    return { deny: `${tag}: spell the branch flag as --branch (or leave it out and the mode supplies it).` }
  }
  const branches = flagValues(args, BRANCH_FLAGS)
  if (branches.length === 0) return { args: requiresBranch(path) ? [...args, '--branch', fde.branchRid] : [...args] }
  if (branches.length === 1 && branches[0] === fde.branchRid) return { args: [...args] }
  const named = branches.filter(Boolean).join(', ') || '(no value)'
  return { deny: `${tag}: ontology writes go to ${fde.branchRid}; this call names --branch ${named}. Drop --branch and the mode supplies it.` }
}

/** The branch's name when `data` (global-branch get) is an OPEN agent/ branch of `ontologyRid`; why not otherwise. */
export function adoptable(data: unknown, ontologyRid: string): { name: string } | string {
  const record = (data as { branch_record?: Record<string, unknown> } | null)?.branch_record
  if (typeof record !== 'object' || record === null) return 'global-branch get returned no branch record.'
  const name = typeof record.display_name === 'string' ? cleanGoal(record.display_name) : ''
  if (record.branch_status !== 'OPEN') return `The branch is ${String(record.branch_status ?? 'unknown')}, not OPEN.`
  if (record.ontology_rid !== ontologyRid) return `The branch belongs to ontology ${String(record.ontology_rid ?? 'unknown')}, not the selected ${ontologyRid}.`
  if (!name.startsWith('agent/') || !validateBranchName('global-branch create', name).ok) return `The branch '${name.slice(0, 80) || '?'}' is not a valid agent/ branch name.`
  return { name }
}

const appliedLines = (fde: FdeSession) =>
  fde.applied.length === 0 ? ['- nothing applied'] : fde.applied.map(entry => `- ${entry.at} ${entry.command}`)

export function fdeContext(fde: FdeSession): string {
  return [
    '# FDE mode',
    `Goal: ${goalLabel(fde.goal)}${fde.goal === '' ? ' (the operator works with you turn by turn; /fde goal sets one)' : ''}`,
    `This session works on one global branch: ${fde.branchName} (${fde.branchRid}) on ontology ${fde.ontologyRid}, stack ${fde.profile}.`,
    'Ontology writes are pinned to it: omit --branch and the mode adds it; any other branch, --profile or a new branch is refused. ' +
      'Pass --branch with that RID on reads you mean to see the branch (`ontology definition --object-type X --branch <rid>`); reads without it see main.',
    'Plan, then apply: run each write as a dry run (no --apply), read the plan, then repeat it with --apply and identical arguments. ' +
      'Each dry run licenses one apply, and editing a file the call reads voids it. Keep request files outside ~/.claude.',
    'Work as an FDE: scout what exists, make the smallest change on the branch, verify it on the branch, then report. ' +
      'Never create, close or merge branches: the operator ends the mode with /fde end and decides what lands.',
  ].join('\n')
}

export function fdeStatus(fde: FdeSession): string {
  return [
    `FDE mode on · ${goalLabel(fde.goal)}`,
    `branch ${fde.branchName} (${fde.branchRid})`,
    `stack ${fde.profile} · ontology ${fde.ontologyRid} · since ${fde.startedAt}`,
    `${fde.applied.length} applied · ${fde.plans.length} planned`,
    '/fde end hands off and leaves the branch open.',
  ].join('\n')
}

export function fdeHandoff(fde: FdeSession): string {
  return [
    `# FDE handoff: ${goalLabel(fde.goal)}`,
    '',
    `- Branch: ${fde.branchName} (${fde.branchRid}), still OPEN and not merged.`,
    `- Stack ${fde.profile}, ontology ${fde.ontologyRid}, started ${fde.startedAt}.`,
    `- Applied writes (${fde.applied.length}):`,
    ...appliedLines(fde).map(line => `  ${line}`),
    '',
    'The operator reviews the branch, then merges it through a proposal or closes it: ' +
      `orthanc global-branch close ${fde.branchRid} --apply --yes.`,
  ].join('\n')
}

